'use strict';
window.CobaltUI={
 t(zh,en){return I18n.language==='en'?en:zh;},
 states:{PREPARING:['备货作业中','Preparation in Progress'],DRAFT:['草稿','Draft'],SITE_PENDING:['待现场主管审核','Awaiting Site Review'],PRODUCTION_PENDING:['待生产管理部审核','Awaiting Production Review'],REJECTED:['已驳回','Rejected'],WITHDRAWN:['已撤销','Withdrawn'],RECEIVED:['已正式入库','Received']},
 status(code){return this.t(...(this.states[code]||[code,code]));},
 can(code){return CurrentUser.permissions.includes(code);},
 error(e){const messages={CO_INVALID_INPUT:['输入字段无效','Invalid input fields'],CO_INVALID_COUNTS:['每批袋数必须为正整数；每单最多100个生产批次、10000袋','Use positive whole bag counts; maximum 100 batches and 10,000 bags per document'],CO_TOTAL_MISMATCH:['生产批次袋数合计与总袋数不一致','Batch quantities do not match the total bag count'],CO_INVALID_BATCH:['生产批次重复、不存在或属于其他项目','Duplicate, missing or wrong-project production batch'],CO_INVALID_WAREHOUSE:['仓库不属于所选项目','Warehouse does not belong to the selected project'],CO_STALE_VERSION:['单据已变化，请刷新后重试','Document changed; refresh and try again'],CO_INVALID_STATE:['当前状态或操作人不允许此操作','This action is not allowed for the current state or actor'],CO_PERMISSION_DENIED:['当前角色无此节点权限','Your role is not authorized for this approval stage'],CO_STATE_CONFLICT:['数据或状态冲突，请刷新核实','Data or state conflict; refresh and verify'],CO_NOT_FOUND:['单据不存在或不在授权范围','Document not found or outside your scope'],CO_PRODUCT_REQUIRED:['请切换至氢氧化钴后操作','Switch to Cobalt Hydroxide first'],CO_KEY_REUSED:['幂等键不能用于不同请求','An idempotency key cannot be reused for different content'],'CO_REASON无效':['请填写原因，最多1000字','Enter a reason, up to 1,000 characters'],'CO_BATCH无效':['请填写有效生产批次，最多80字','Enter a production batch code, up to 80 characters']};return messages[e.message]?this.t(...messages[e.message]):I18n.translate(e.message,true);},
 page(title,html){Router.page(title,'<div class="co-page" data-no-i18n>'+html+'</div>');for(const table of document.querySelectorAll('.co-page table'))table.dataset.v34Enhanced='true';for(const form of document.querySelectorAll('.co-page form'))form.dataset.v34Reset='true';},
 async route(path){try{if(path==='/preparation/new')await this.create();else if(path==='/preparation')await this.list();else await this.detail(path.split('/')[2]);}catch(e){this.page(this.t('氢氧化钴备货','Cobalt Preparation'),'<p class="error" role="alert">'+esc(this.error(e))+'</p>');}},
 async languageChanged(){const state=document.getElementById('co-create')?this.formValue():null,dirty=ProductContext.dirty;try{if(state)await this.create(state);else await this.route(location.pathname);}finally{ProductContext.dirty=dirty;}},
 async list(){const params=new URLSearchParams(location.search),status=params.get('status')||'',page=Number(params.get('page')||1),d=await API.request('/cobalt/preparations?'+new URLSearchParams({status,page}));this.page(this.t('氢氧化钴备货单','Cobalt Preparation Orders'),`<div class="business-toolbar">${this.can('co:create')?`<a id="co-new" class="button primary" href="/preparation/new">${this.t('新建备货单','Create Preparation')}</a>`:''}<form id="co-filter" class="filters"><label>${this.t('单据状态','Status')}<select name="status"><option value="">${this.t('全部','All')}</option>${Object.keys(this.states).map(s=>`<option value="${s}" ${s===status?'selected':''}>${this.status(s)}</option>`).join('')}</select></label><button class="button secondary">${this.t('查询','Search')}</button></form></div><p>${this.t('备货单不绑定客户或销售合同。生产管理部审核后生成备货作业中库存。','No customer or contract is assigned. Production approval creates physical stock in preparation.')}</p><div class="business-table"><table><thead><tr>${[this.t('备货单号','Order'),this.t('备货批次','Preparation Batch'),this.t('业务日期','Business Date'),this.t('袋数','Bags'),this.t('预计净重（kg）','Expected Net (kg)'),this.t('状态','Status')].map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${d.items.map(p=>`<tr><td><a href="/preparation/${p.id}">${esc(p.document_no)}</a></td><td>${esc(p.preparation_batch_no)}</td><td>${esc(p.business_date)}</td><td>${p.bag_count}</td><td>${Number(p.expected_net_kg).toLocaleString()}</td><td>${this.status(p.status)}</td></tr>`).join('')||`<tr><td colspan="6">${this.t('暂无备货单','No preparation orders')}</td></tr>`}</tbody></table></div><div class="co-pager"><button id="co-prev" class="button secondary" ${page<=1?'disabled':''}>${this.t('上一页','Previous')}</button><span>${page} / ${Math.max(1,Math.ceil(d.total/50))}</span><button id="co-next" class="button secondary" ${page*50>=d.total?'disabled':''}>${this.t('下一页','Next')}</button></div>`);$('co-filter').onsubmit=e=>{e.preventDefault();Router.go('/preparation?'+new URLSearchParams({status:e.target.elements.status.value}));};for(const [id,delta] of [['co-prev',-1],['co-next',1]])$(id).onclick=()=>Router.go('/preparation?'+new URLSearchParams({status,page:page+delta}));ProductContext.dirty=false;},
 formValue(){const form=$('co-create');return {project_id:form.elements.project_id.value,warehouse_id:form.elements.warehouse_id.value,lines:[...form.querySelectorAll('[data-co-line]')].map(row=>({production_batch_code:row.querySelector('[data-co-code]').value,bag_count:Number(row.querySelector('[data-co-count]').value)}))};},
 async create(saved){const opts=await API.request('/cobalt/options'),project=saved?.project_id||opts.projects[0]?.id;this.page(this.t('新建氢氧化钴备货单','Create Cobalt Preparation'),`<form id="co-create"><div class="form-grid"><label>${this.t('项目','Project')}<select name="project_id" required>${opts.projects.map(p=>`<option value="${p.id}" ${p.id===project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>${this.t('仓库','Warehouse')}<select name="warehouse_id" required></select></label></div><p class="co-note">${this.t('每单生成一个备货批次。日期由服务器按卢本巴希时区确认；袋号在保存时正式分配。','Each order creates one preparation batch. The server uses the Lubumbashi business date; bag numbers are assigned when saved.')}</p><div class="business-table"><table><thead><tr><th>${this.t('生产批次','Production Batch')}</th><th>${this.t('袋数','Bag Count')}</th><th>${this.t('操作','Action')}</th></tr></thead><tbody id="co-lines"></tbody></table></div><button id="co-add-line" type="button" class="button secondary">${this.t('增加生产批次','Add Production Batch')}</button><p class="co-totals" id="co-totals" aria-live="polite"></p><p>${this.t('初始预计每袋：毛重650kg，包装3kg，净重647kg。本版不开放逐袋重量修改。','Initial expected weight per bag: gross 650 kg, packaging 3 kg, net 647 kg. Individual weight editing is unavailable in this version.')}</p><p class="error" id="co-error" role="alert"></p><button class="button primary" id="co-save" type="submit">${this.t('保存备货单','Save Preparation')}</button></form>`);
 const warehouse=()=>{$('co-create').elements.warehouse_id.innerHTML=opts.warehouses.filter(w=>w.project_id===$('co-create').elements.project_id.value).map(w=>`<option value="${w.id}" ${saved?.warehouse_id===w.id?'selected':''}>${esc(w.name)}</option>`).join('');};warehouse();$('co-create').elements.project_id.onchange=warehouse;
 const totals=()=>{const n=[...$('co-lines').querySelectorAll('[data-co-count]')].reduce((s,e)=>s+Number(e.value||0),0);$('co-totals').textContent=this.t('合计 '+n+' 袋 · 预计毛重 '+(n*650).toLocaleString()+' kg · 预计净重 '+(n*647).toLocaleString()+' kg',n+' bags · Expected gross '+(n*650).toLocaleString()+' kg · Expected net '+(n*647).toLocaleString()+' kg');};
 const add=(line={})=>{const row=document.createElement('tr');row.dataset.coLine='';row.innerHTML=`<td><input data-co-code aria-label="${this.t('生产批次','Production Batch')}" maxlength="80" required value="${esc(line.production_batch_code||'')}"></td><td><input data-co-count aria-label="${this.t('袋数','Bag Count')}" type="number" min="1" max="10000" step="1" required value="${line.bag_count||1}"></td><td><button type="button" data-co-remove class="button secondary">${this.t('删除行','Remove')}</button></td>`;row.querySelector('[data-co-remove]').onclick=()=>{if($('co-lines').children.length>1){row.remove();totals();}};row.oninput=totals;$('co-lines').append(row);totals();};for(const line of saved?.lines||[{}])add(line);$('co-add-line').onclick=()=>{if($('co-lines').children.length<100)add();};
 $('co-create').onsubmit=async e=>{e.preventDefault();const button=$('co-save');button.disabled=true;$('co-error').textContent='';try{const b=this.formValue(),total=b.lines.reduce((n,l)=>n+l.bag_count,0);const p=await API.request('/cobalt/preparations',{method:'POST',body:{...b,total_bags:total}});ProductContext.dirty=false;await Router.go('/preparation/'+p.id);}catch(err){$('co-error').textContent=this.error(err);button.disabled=false;}};
 },
 async detail(id){const page=Number(new URLSearchParams(location.search).get('bag_page')||1),d=await API.request('/cobalt/preparations/'+id+'?bag_page='+page);const review=d.status==='SITE_PENDING'&&['site_supervisor','admin'].includes(CurrentUser.role_code)&&this.can('co:site-review')?'site-approve':d.status==='PRODUCTION_PENDING'&&['production_manager','admin'].includes(CurrentUser.role_code)&&this.can('co:production-review')?'production-approve':null,own=d.created_by===CurrentUser.id;
 const actions=[];if(own&&this.can('co:submit')&&['DRAFT','REJECTED'].includes(d.status))actions.push(['submit',this.t('提交现场审核','Submit for Site Review')]);if(review&&!own){actions.push([review,this.t('审核通过','Approve')],['reject',this.t('驳回','Reject')]);}if(own&&this.can('co:withdraw')&&['DRAFT','REJECTED','SITE_PENDING'].includes(d.status))actions.push(['withdraw',this.t('撤销备货单','Withdraw')]);
 this.page(this.t('氢氧化钴备货详情','Cobalt Preparation Details'),`<div class="co-document"><strong>${esc(d.preparation_batch_no||d.document_no)}</strong><span class="title-chip" id="co-status">${this.status(d.status)}</span></div><dl><dt>${this.t('备货批次','Preparation Batch')}</dt><dd>${esc(d.preparation_batch_no)}</dd><dt>${this.t('创建业务日期（卢本巴希）','Creation Business Date (Lubumbashi)')}</dt><dd>${esc(d.business_date)}</dd><dt>${this.t('袋数 / 预计净重','Bags / Expected Net Weight')}</dt><dd>${d.bag_count} / ${(d.bag_count*647).toLocaleString()} kg</dd></dl><ol class="co-steps">${[this.t('物流操作员提交','Logistics Submission'),this.t('现场主管审核','Site Supervisor Review'),this.t('生产管理部审核并入库','Production Review and Receipt')].map((s,i)=>`<li class="${(i===0&&d.submitted_at||i===1&&d.site_reviewed_at||i===2&&d.production_reviewed_at)?'co-step-done':''}">${s}</li>`).join('')}</ol><div class="co-inventory"><strong id="co-physical">${this.t('实物库存','Physical Stock')}: ${d.inventory.physical_bags} ${this.t('袋','bags')}</strong><span>${this.t('可装车库存','Loadable Stock')}: 0</span><span>${d.status==='RECEIVED'?(AppConfig.cobaltWorkV39?CobaltWorkUI.status(d.work?.status||'PREPARING'):this.t('库存状态：备货作业中','Inventory status: Preparation in Progress')):this.t('尚未正式入库','Not yet received')}</span></div><p class="co-note">${AppConfig.cobaltWorkV39?this.t('本版本不开放装车匹配或正式出库。','Loading matching and outbound posting are unavailable in this version.'):this.t('V3.8不开放备货完成、装车匹配或正式出库。','Preparation completion, loading matching and outbound posting are unavailable in V3.8.')}</p><div class="business-toolbar">${actions.map(([a,n])=>`<button data-co-action="${a}" class="button ${a==='reject'||a==='withdraw'?'secondary':'primary'}">${n}</button>`).join('')}${AppConfig.cobaltWorkV39&&d.status==='RECEIVED'?`<a id="co-work-open" class="button primary" href="/preparation/${d.id}/work">${this.t('备货作业','Preparation Work')}</a><span class="title-chip">${CobaltWorkUI.status(d.work?.status||'PREPARING')}</span>`:''}<a class="button secondary" href="/preparation">${this.t('返回列表','Back to List')}</a></div><p id="co-error" class="error" role="alert"></p><h2>${this.t('生产批次分配','Production Batch Allocation')}</h2><div class="business-table"><table><thead><tr><th>${this.t('生产批次','Production Batch')}</th><th>${this.t('袋数','Bags')}</th></tr></thead><tbody>${d.lines.map(l=>`<tr><td>${esc(l.production_batch_code)}</td><td>${l.bag_count}</td></tr>`).join('')}</tbody></table></div><h2>${this.t('袋号与预计重量','Bag Numbers and Expected Weights')}</h2><div class="business-table"><table id="co-bags"><thead><tr>${[this.t('袋号','Bag Number'),this.t('生产批次','Production Batch'),this.t('预计毛重（kg）','Expected Gross (kg)'),this.t('包装（kg）','Packaging (kg)'),this.t('预计净重（kg）','Expected Net (kg)')].map(s=>'<th>'+s+'</th>').join('')}</tr></thead><tbody>${d.bags.map(b=>`<tr><td>${esc(b.bag_no)}</td><td>${esc(b.production_batch_code)}</td><td>${+b.expected_gross_kg}</td><td>${+b.packaging_kg}</td><td>${+b.expected_net_kg}</td></tr>`).join('')}</tbody></table></div><div class="co-pager"><button id="co-bag-prev" class="button secondary" ${page<=1?'disabled':''}>${this.t('上一页','Previous')}</button><span>${page} / ${Math.ceil(d.bag_count/200)}</span><button id="co-bag-next" class="button secondary" ${page*200>=d.bag_count?'disabled':''}>${this.t('下一页','Next')}</button></div><h2>${this.t('审批历史','Approval History')}</h2><div class="business-table"><table id="co-history"><thead><tr><th>${this.t('时间','Time')}</th><th>${this.t('操作人','Actor')}</th><th>${this.t('状态','Status')}</th><th>${this.t('原因','Reason')}</th></tr></thead><tbody>${d.events.map(e=>`<tr><td>${esc(BusinessTime.display(e.occurred_at))}</td><td>${esc(I18n.language==='en'?(e.actor_name_en||EmployeeIdentity.name({display_name:e.actor_name})):e.actor_name)}</td><td>${this.status(e.to_status)}</td><td>${esc(e.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`);
 for(const button of document.querySelectorAll('[data-co-action]'))button.onclick=async()=>{const action=button.dataset.coAction;let reason='';const needsReason=['reject','withdraw'].includes(action);if(!await OperationConfirm.ask({title:button.textContent,rows:[[this.t('备货单','Preparation'),d.document_no]],comment:needsReason,commentRequired:needsReason,commentLabel:this.t('原因（必填）','Reason (required)'),onComment:value=>reason=value}))return;button.disabled=true;try{await API.request('/cobalt/preparations/'+id+'/'+action,{method:'POST',body:{version:d.version,...(needsReason?{reason}:{})}});ProductContext.dirty=false;await this.detail(id);}catch(e){$('co-error').textContent=this.error(e);button.disabled=false;}};
 for(const [button,delta] of [['co-bag-prev',-1],['co-bag-next',1]])$(button).onclick=()=>Router.go('/preparation/'+id+'?bag_page='+(page+delta));ProductContext.dirty=false;
 }
};
Object.assign(Accounts.permissionLabels,{'co:read':'氢氧化钴备货查看','co:create':'氢氧化钴备货创建','co:submit':'氢氧化钴备货提交','co:site-review':'氢氧化钴现场审核','co:production-review':'氢氧化钴生产审核','co:withdraw':'氢氧化钴备货撤销'});
Accounts.groups.co='氢氧化钴备货与入库';
Object.assign(TRANSLATIONS.en,{'氢氧化钴备货查看':'View Cobalt Preparations','氢氧化钴备货创建':'Create Cobalt Preparations','氢氧化钴备货提交':'Submit Cobalt Preparations','氢氧化钴现场审核':'Cobalt Site Review','氢氧化钴生产审核':'Cobalt Production Review','氢氧化钴备货撤销':'Withdraw Cobalt Preparations','氢氧化钴备货与入库':'Cobalt Preparation and Receipt','已确认钴业务操作结果':'Cobalt operation confirmed','结果尚未确认，请保留原幂等键':'Result unknown; retain the original idempotency key'});
I18n.pattern=new RegExp(Object.keys(TRANSLATIONS.en).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
